import{_ as r}from"./chunks/KEITH_RICHARDS_MESA_03.BE98nuu1.js";import{o as i,c as s,a0 as n,j as a,t as l,p as m}from"./chunks/framework.L_oL6aia.js";const p={class:"rock-card-contact"},d={class:"rock-copy-email-wrapper"},k=JSON.parse(`{"title":"'78–'81年の軌跡：ローリング・ストーンズとMesa/Boogieの出会い","description":"","frontmatter":{"layout":"doc","title":"'78–'81年の軌跡：ローリング・ストーンズとMesa/Boogieの出会い"},"headers":[],"relativePath":"ja/history-mesa-stones.md","filePath":"ja/history-mesa-stones.md"}`),c={name:"ja/history-mesa-stones.md"},M=Object.assign(c,{setup(u){const o=m("メールアドレスをコピー");function t(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),o.value="コピーしました！",setTimeout(function(){o.value="メールアドレスをコピー"},2e3)}return(g,e)=>(i(),s("div",null,[e[3]||(e[3]=n('<h1 id="_78–-81年の軌跡-ローリング・ストーンズとmesa-boogieの出会い" tabindex="-1">&#39;78–&#39;81年の軌跡：ローリング・ストーンズとMesa/Boogieの出会い <a class="header-anchor" href="#_78–-81年の軌跡-ローリング・ストーンズとmesa-boogieの出会い" aria-label="Permalink to &quot;&#39;78–&#39;81年の軌跡：ローリング・ストーンズとMesa/Boogieの出会い&quot;">​</a></h1><p><strong>スタジオアーカイブ＆トーン探究記 · Main St Audio Labs</strong></p><hr><img src="'+r+'" alt="Keith Richards with his Mesa Boogie Mark I" style="max-height:400px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><p>1970年代後半、ローリング・ストーンズがアルバム『<em>Some Girls</em>（女たち）』のツアーと伝説的なスタジオセッションを準備していた頃、彼らの象徴的なギタートーンを決定づける重要な機材が誕生しました。それはロンドンの巨大工場ではなく、カリフォルニア州の小さな工房で生まれたのです。キース・リチャーズとストーンズが伝説の100W Mesa/Boogie Mark Iアンプを手に入れたストーリーは、ロックの歴史において非常に興味深い一章です。</p><h2 id="boogie-の誕生" tabindex="-1">Boogie の誕生 <a class="header-anchor" href="#boogie-の誕生" aria-label="Permalink to &quot;Boogie の誕生&quot;">​</a></h2><p>物語は、カリフォルニア州ラグニタス／ミルバレーの楽器店「Prune Music」の裏で、小さなFender Princetonコンボアンプの改造を手がけていたランドール（ランディ）・スミスから始まります。スミスはこれらの手頃な練習用アンプをホットロッド改造し、巨大なBassmanのトランスフォーマーとハイゲイン回路を詰め込みました。</p><p>カルロス・サンタナがこの初期の改造プロトタイプを弾いた際、<em>&quot;Man, that little thing really boogies!&quot;</em>（おい、この小さなやつは本当にブギウギ踊り出すぜ！）と叫んだことから、「Mesa/Boogie」の名が生まれたという逸話は有名です。</p><p>これらの初期の Mark I アンプは革新的でした。コンパクトな1x12インチの筐体の中に、実に100ワットRMSという驚異的なパワーを詰め込んでいたのです。この圧倒的な出力に耐えられるよう、スミスはElectro-Voice EVM-12LやAltec 417などの高耐入力スピーカーを美しい無垢材（ハードウッド）のキャビネットに収めました。Mark Iは現代のようなチャンネル切り替え方式ではなく、2つのインプットを備えていました。Input 1は12AX7真空管を多段ドライブさせた伸びやかなリードトーン、Input 2は1段バイパスしたホットロッドFender風のクリーン〜リズムトーンを生み出しました。</p><h2 id="イアン・スチュワートからの電話" tabindex="-1">イアン・スチュワートからの電話 <a class="header-anchor" href="#イアン・スチュワートからの電話" aria-label="Permalink to &quot;イアン・スチュワートからの電話&quot;">​</a></h2><p>1977年初頭、ストーンズは14年ぶりとなるクラブ公演（カナダ・トロントのエル・モカンボ公演。後に名盤『<em>Love You Live</em>』のC面となる演奏）を控えていました。この桁外れに音量が大きく、ピッキングの強弱に繊細に反応するカリフォルニア製アンプの噂は、ストーンズ陣営の耳にも届いていました。</p><p>ランディ・スミスの回想によると、それは一本の予期せぬ電話から始まりました： <em>「当時、アンプ作りは完全に家内制手工業で、私がすべて一人でやっていました。電話を取ると、ストーンズのピアニストであるイアン・スチュワートでした。『Boogieを試してみたいんだ。噂をたくさん聞いている。何台か送ってくれないか？』と彼は言いました。私は答えました。『それはできません。私は一人でやっている工房ですし、アンプをタダであげることはしていません』。すると彼は『俺たちはローリング・ストーンズだぞ。アンプに金を払ったことなんてない』と言ったのです。」</em></p><p>この押し問答の最中、スミスは受話器の向こうからキース・リチャーズがスチュワートに指示を出している声を耳にしました。スミスはキースと直接話したいと頼みました。</p><p><em>「キースが電話口に出てくれました。彼は本当に素晴らしい、最高にフレンドリーな男でした」<em>とスミスは語ります。</em>「『よう、調子はどうだい？ あんたのアンプを手に入れたいんだ』と彼は言いました。同じ説明をすると、キースは『でもさ、金を払うなんてピンとこないな。俺たちは長いこと機材に金を払ってないんだ』と言いました。私は『でも、私は食うや食わずの貧乏な職人ですから、機材をタダで配るわけにはいかないんです……』と返しました。」</em></p><p>世界最大のロックバンドを相手に、スミスは大胆な賭けに出ました。「まずは購入してほしい。もし気に入らなければ全額返金する。あるいは、今Boogieには長い予約待ちリストがあるから、気に入らなければ他へ転売して利益を出してもいい」と提案したのです。</p><p>受話器の向こうで長い沈黙が流れた後、キースはこう答えました： <em>「まあ、そうだな相棒。そいつは名案だ。……ただ一つ問題がある。俺はそのアンプが欲しいってことが最初からもう分かってるんだ。疑いようもない。サンタナが俺たちと共演した時にあいつのやつを弾いたからね。そして、1台じゃ足りない。6台欲しいんだ。」</em></p><h2 id="伝説のステージとスタジオへ" tabindex="-1">伝説のステージとスタジオへ <a class="header-anchor" href="#伝説のステージとスタジオへ" aria-label="Permalink to &quot;伝説のステージとスタジオへ&quot;">​</a></h2><p>こうして手に入れた最初の6台のMesa/Boogie Mark I（5バンド・グラフィックEQと高耐入力スピーカーを搭載）は、その後の約5年間にわたりストーンズのギタートーンの核となりました。</p><p>1977年3月のエル・モカンボ公演の写真には、キースとロニー・ウッドが新しいハードウッド製Boogieを鳴らしている姿がはっきりと写っています。キースのアンプのTrebleノブのすぐ上には、このライブの最中についた有名なタバコの焦げ跡が残されました。</p><p>これらのアンプは同年末、名盤『<em>Some Girls</em>（女たち）』のセッションのためにパリの<em>Pathé Marconi Studios</em>へ運ばれました。100W 6L6パワー管による圧倒的なヘッドルームと明瞭なアタック感、そしてグラフィックEQによる緻密な音作りにより、キースとロニーは太く抜けが良いクリーンでありながら、適度なバイト感と粘りを持つトーンを構築しました。「Beast of Burden」や「Shattered」といった楽曲のミックスを鮮やかに切り裂くギタートーンは、こうして完成したのです。</p><p>Boogieはその後、『<em>Emotional Rescue</em>』（1979-1980年、バハマのコンパス・ポイントおよびパリ）や『<em>Tattoo You</em>』（1981年）のレコーディングでもメイン機材として活躍し続けました。ストーンズはその後数年間で、実に40台以上のMesa/Boogieアンプを正規に購入することになります。</p><h2 id="時代の変遷とルーツへの帰還" tabindex="-1">時代の変遷とルーツへの帰還 <a class="header-anchor" href="#時代の変遷とルーツへの帰還" aria-label="Permalink to &quot;時代の変遷とルーツへの帰還&quot;">​</a></h2><p>Mesa/Boogie Mark I（およびその後のMark II、Mark III）は、10年以上にわたってキースのリグの中心であり続けました。1989年の巨大な『<em>Steel Wheels</em>』ツアーを支え、1992〜1993年のソロプロジェクト『<em>X-Pensive Winos</em>』のツアーでも大活躍しました。実際、1977年の最初のMark I（シリアルナンバー A804）は、&#39;92年のWinosツアー直前にカリフォルニアのMesa工場へ送られ、オーバーホールを受けています。</p><p>しかし1990年代半ば（『<em>Voodoo Lounge</em>』や『<em>Bridges to Babylon</em>』）になると、キースは自身の原点へと回帰し始めます。1950年代の<strong>Fender Tweed</strong>アンプ（特にハイパワーTweed TwinやTweed Deluxe）が持つ、ルーズでオーガニック、適度にコンプレッションのかからないナチュラルなドライブ感へと再び魅了され、それが現在に至る彼のサウンドの代名詞となっていきました。</p><blockquote><p>🎸 <strong>50年代の生々しいTweedトーンをお探しですか？</strong><br> キースが最終的に回帰した、50年代Tweedアンプのピッキングに追従するリアルなドライブ感を体験したい方は、当ラボの <strong><a href="/ja/midnight-rambler.html">Midnight Rambler プラグイン</a></strong> をご覧ください。伝説のTweed Deluxe（5E3）をニューラルネットワークで忠実にモデリングしています。</p></blockquote><p>タバコの焦げ跡がついた1977年製の初代Mark Iは今も現存しており、カリフォルニアの小さなブティック工房が世界最高のロックンロールバンドのサウンドを再定義した歴史的瞬間を静かに物語っています。</p><blockquote><p><em>出典：Dave Hunter著『Keith Richards’ 1977 Mesa/Boogie Mark I』（Vintage Guitar® magazineより要約）。</em></p></blockquote><hr><div style="text-align:center;margin:2rem 0;"><a href="/ja/tattoo-you" class="rock-btn rock-btn-primary" style="display:inline-block;padding:0.6rem 1.5rem;">← Tattoo You マニュアルへ戻る</a></div>',29)),a("div",p,[e[1]||(e[1]=a("div",{class:"rock-card-contact-title"},"貴重な写真やセッション情報をお持ちですか？",-1)),e[2]||(e[2]=a("p",{class:"rock-card-contact-desc"},"70年代後半から80年代初頭のストーンズのスタジオ機材に関する貴重な情報やエピソードをお持ちの方は、ぜひご連絡ください：",-1)),a("div",d,[e[0]||(e[0]=a("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),a("button",{class:"rock-copy-btn",onClick:t},l(o.value),1)])])]))}});export{k as __pageData,M as default};
